const fence = String.fromCharCode(96).repeat(3);
const raw = String($json.text ?? $json.output ?? '').replace(new RegExp('^' + fence + 'json\\s*','i'), '').replace(new RegExp(fence + '$'),'').trim();
let extraction;
try { extraction = JSON.parse(raw); } catch { throw new Error('Extrator não retornou JSON válido.'); }
const state = { ...$('Preparar estado do lead').item.json.lead_state };
const allowed = new Set(['nome','empresa','segmento','origem_lead','volume_contatos','origem_contatos','precisa_mais_contatos','demora_resposta','mensagens_fora_horario','duvidas_repetitivas','depende_indicacoes','anuncios_atuais','verba_midia','capacidade_atendimento','tipo_operacao','leads_sem_retorno','base_inativos','agenda_estruturada','follow_up_estruturado','registra_conversoes','pacote_de_interesse','prioridade_gargalo']);

for (const [key, value] of Object.entries(extraction.fatos_novos || {})) {
  if (allowed.has(key) && value !== null && value !== '' && value !== 'desconhecido') state[key] = value;
}

// PROTECAO: a IA extratora as vezes coloca o sinal de autorizacao de continuidade dentro
// de fatos_novos (como string 'sim') em vez do campo de controle de nivel superior
// esperado (extraction.autoriza_continuidade: true/false). Isso ja causou um bug serio
// (o motor nunca reconhecia a autorizacao do cliente e o handoff nunca era registrado de
// verdade). Normalizamos aqui reconhecendo as duas formas possiveis, para nao depender
// de a IA acertar sempre o formato exato.
const autorizouExplicitamente =
  extraction.autoriza_continuidade === true ||
  extraction.fatos_novos?.autoriza_continuidade === true ||
  String(extraction.fatos_novos?.autoriza_continuidade || '').toLowerCase() === 'sim';
extraction.autoriza_continuidade = autorizouExplicitamente;

const currentIntent = state.intencao || 'desconhecida';
let newIntent = currentIntent;
if (extraction.opt_out) {
  newIntent = 'outro';
} else if (extraction.pedido_humano) {
  newIntent = 'humano';
} else if (['humano', 'suporte'].includes(currentIntent) &&
  (!extraction.intencao_detectada || extraction.intencao_detectada === 'desconhecida')) {
  // Uma mensagem neutra posterior nao deve herdar indefinidamente a intencao humana.
  newIntent = 'outro';
} else if (extraction.intencao_detectada && extraction.intencao_detectada !== 'desconhecida') {
  const intencoesEspecificas = ['site_avulso', 'comparacao_site_pacotes', 'pacotes', 'humano', 'suporte'];
  if (intencoesEspecificas.includes(extraction.intencao_detectada)) {
    newIntent = extraction.intencao_detectada;
  } else if (extraction.intencao_detectada === 'outro') {
    if (currentIntent === 'desconhecida') newIntent = 'outro';
  }
}
state.intencao = newIntent;

state.ultima_interacao_em = new Date().toISOString();
return [{ json: { state, extraction } }];

const state = { ...$json.state };
const ex = $json.extraction || {};
const PACKAGES = {
  atendimento_presenca: 'Presença Digital Inteligente',
  aquisicao: 'Máquina de Clientes',
  processo_conversao: 'Crescimento Automatizado'
};

let route = 'diagnostico';
let nextQuestion = null;
let decision = null;

function setQuestion(text, fields = []) {
  nextQuestion = text;
  state.ultima_pergunta = text;
  state.campos_pendentes = fields.length ? fields : [text];
}

function recommend(gargalo) {
  state.estado_funil = 'RECOMENDACAO_PRONTA';
  state.gargalo_principal = gargalo;
  state.prioridade_gargalo = gargalo;
  state.pacote_recomendado = PACKAGES[gargalo];
  state.pacote_de_interesse = state.pacote_recomendado;
  state.pacote_etapa = 'aguardando_confirmacao_proposta';
  state.ultima_pergunta = 'Faz sentido seguirmos com o ' + state.pacote_recomendado + '?';
  state.campos_pendentes = ['confirmacao_proposta'];
  decision = {
    status_decisao: 'RECOMENDACAO_PRONTA',
    pacote_recomendado: state.pacote_recomendado,
    gargalo_principal: gargalo,
    regra_aplicada: 'FUNIL_IA_V1'
  };
  route = 'diagnostico';
}

function diagnosticSignals() {
  const pdi = ['demora_resposta','mensagens_fora_horario','duvidas_repetitivas']
    .some(k => state[k] === 'sim');
  const mcSignal = state.volume_contatos === 'baixo' ||
    state.depende_indicacoes === 'sim' ||
    state.precisa_mais_contatos === 'sim';
  const caSignal = ['leads_sem_retorno','base_inativos'].some(k => state[k] === 'sim') ||
    state.agenda_estruturada === 'nao' ||
    state.follow_up_estruturado === 'nao' ||
    state.registra_conversoes === 'nao';

  const candidates = [];
  if (pdi) candidates.push('atendimento_presenca');
  if (mcSignal && state.capacidade_atendimento === 'sim' && state.verba_midia === 'sim') {
    candidates.push('aquisicao');
  }
  if (caSignal && ['medio','alto'].includes(state.volume_contatos)) {
    candidates.push('processo_conversao');
  }
  return { pdi, mcSignal, caSignal, candidates: [...new Set(candidates)] };
}

function runDiagnosis() {
  state.estado_funil = 'DIAGNOSTICO_EM_ANDAMENTO';
  route = 'diagnostico';

  const { pdi, mcSignal, caSignal, candidates } = diagnosticSignals();
  const volumeContatosNormalizado = String(state.volume_contatos ?? '')
    .trim()
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '');
  const volumeContatosNaoInformado = !volumeContatosNormalizado ||
    ['desconhecido', 'nao informado', 'nao_informado', 'indefinido'].includes(volumeContatosNormalizado);
  state.gargalos_candidatos = candidates;

  if (state.prioridade_gargalo && candidates.includes(state.prioridade_gargalo)) {
    recommend(state.prioridade_gargalo);
    return;
  }

  if (candidates.length > 1) {
    state.estado_funil = 'PRECISA_DESEMPATE';
    setQuestion(
      'Qual desses problemas causa mais perda hoje: demora no atendimento, falta de novos contatos ou falta de acompanhamento depois do primeiro contato?',
      ['prioridade_gargalo']
    );
    return;
  }

  if (candidates.length === 1) {
    recommend(candidates[0]);
    return;
  }

  if (mcSignal && !state.capacidade_atendimento) {
    setQuestion('Sua empresa conseguiria atender um aumento de procura?', ['capacidade_atendimento']);
    return;
  }

  if (mcSignal && !state.verba_midia) {
    setQuestion('Existe disponibilidade para investir em mídia paga além da mensalidade do serviço?', ['verba_midia']);
    return;
  }

  if (caSignal && volumeContatosNaoInformado) {
    setQuestion('Hoje sua empresa já recebe contatos com frequência ou ainda precisa gerar mais oportunidades?', ['volume_contatos','precisa_mais_contatos']);
    return;
  }

  if (volumeContatosNaoInformado && !pdi) {
    setQuestion('Hoje sua empresa já recebe contatos com frequência ou precisa gerar mais clientes?', ['volume_contatos','precisa_mais_contatos']);
    return;
  }

  if (!mcSignal && !state.demora_resposta) {
    setQuestion('Você costuma demorar para responder ou recebe mensagens fora do horário?', ['demora_resposta','mensagens_fora_horario']);
    return;
  }

  if (!state.depende_indicacoes) {
    setQuestion('Hoje o negócio depende principalmente de indicações para conseguir novos contatos?', ['depende_indicacoes']);
    return;
  }

  if (!state.follow_up_estruturado) {
    setQuestion('Depois do primeiro contato, vocês têm um processo organizado de acompanhamento e retorno?', ['follow_up_estruturado']);
    return;
  }

  state.estado_funil = 'PRECISA_CONFIRMACAO';
  state.precisa_confirmacao = true;
  setQuestion('O que mais pesa hoje no seu negócio: responder rápido, gerar novos contatos ou acompanhar melhor quem já entrou em contato?', ['prioridade_gargalo']);
}

const persistedStatus = String(state.estado_funil || 'NOVO');
if (persistedStatus === 'HANDOFF_PENDENTE') state.handoff_status = 'PENDENTE';
if (persistedStatus === 'HANDOFF_CONFIRMADO') state.handoff_status = 'CONFIRMADO';

if (typeof state.atendimento_humano_ativo !== 'boolean') {
  state.atendimento_humano_ativo = false;
}
const handoffNotificadoEmMs = Date.parse(state.handoff_notificado_em || '');
const handoffJaNotificado = persistedStatus === 'HANDOFF_PENDENTE' &&
  Number.isFinite(handoffNotificadoEmMs) &&
  (Date.now() - handoffNotificadoEmMs) < 5 * 60 * 1000;

const explicitReauthorization = ex.reautoriza_atendimento === true;
const afirmou = ex.autoriza_continuidade === true || state.autoriza_continuidade === 'sim';

const siteAvulsoEtapaAtual = state.site_avulso_etapa || null;
const siteAvulsoAutorizouRegistro = state.intencao === 'site_avulso' &&
  siteAvulsoEtapaAtual === 'aguardando_autorizacao_registro' &&
  afirmou;

const pacoteAutorizouProposta =
  state.pacote_etapa === 'aguardando_confirmacao_proposta' && afirmou;

const explicitContinuation = ex.pede_proposta === true ||
  siteAvulsoAutorizouRegistro ||
  pacoteAutorizouProposta;

const currentHumanRequest = ex.pedido_humano === true ||
  ['humano', 'suporte'].includes(ex.intencao_detectada);

if (ex.opt_out === true) {
  state.estado_funil = 'OPT_OUT';
  route = 'opt_out';
} else if (persistedStatus === 'OPT_OUT' && !explicitReauthorization) {
  state.estado_funil = 'OPT_OUT';
  route = 'opt_out';
} else if (persistedStatus === 'ENCERRADO') {
  route = 'encerrado';
} else if (currentHumanRequest) {
  if (!['HANDOFF_PENDENTE','HANDOFF_CONFIRMADO'].includes(persistedStatus)) state.estado_funil_antes_handoff = persistedStatus;
  state.handoff_status = 'PENDENTE';
  state.handoff_should_notify = !handoffJaNotificado;
  if (!handoffJaNotificado) state.handoff_notificado_em = new Date().toISOString();
  state.estado_funil = 'HANDOFF_PENDENTE';
  route = 'handoff';
} else if (explicitContinuation) {
  if (!['HANDOFF_PENDENTE','HANDOFF_CONFIRMADO'].includes(persistedStatus)) state.estado_funil_antes_handoff = persistedStatus;
  state.handoff_status = 'PENDENTE';
  state.handoff_should_notify = !handoffJaNotificado;
  if (!handoffJaNotificado) state.handoff_notificado_em = new Date().toISOString();
  state.estado_funil = 'HANDOFF_PENDENTE';
  state.site_avulso_etapa = siteAvulsoAutorizouRegistro
    ? 'handoff_solicitado'
    : state.site_avulso_etapa;
  state.pacote_etapa = pacoteAutorizouProposta
    ? 'handoff_solicitado'
    : state.pacote_etapa;
  route = 'handoff';
} else if (state.intencao === 'site_avulso') {
  state.estado_funil = 'INTENCAO_IDENTIFICADA';
  state.pacote_de_interesse = 'Site institucional avulso';
  route = 'site_avulso';
  if (siteAvulsoEtapaAtual === 'handoff_solicitado') {
    state.site_avulso_etapa = 'handoff_solicitado';
  } else if (!state.segmento) {
    state.site_avulso_etapa = 'aguardando_segmento';
  } else if (!siteAvulsoEtapaAtual || siteAvulsoEtapaAtual === 'aguardando_segmento') {
    state.site_avulso_etapa = 'aguardando_confirmacao_explicacao_materiais';
  } else if (siteAvulsoEtapaAtual === 'aguardando_confirmacao_explicacao_materiais' && afirmou) {
    state.site_avulso_etapa = 'aguardando_autorizacao_registro';
  }
} else if (persistedStatus === 'DIAGNOSTICO_EM_ANDAMENTO' ||
           persistedStatus === 'PRECISA_DESEMPATE' ||
           ex.pede_indicacao === true) {
  runDiagnosis();
} else if (state.intencao === 'comparacao_site_pacotes') {
  state.estado_funil = 'INTENCAO_IDENTIFICADA';
  if (ex.escolha_comparacao === 'diagnostico') {
    state.desempate_comparacao_feito = true;
    runDiagnosis();
  } else {
    route = 'comparacao';
    state.pacotes_apresentados = true;
  }
} else if (state.intencao === 'pacotes') {
  state.estado_funil = 'INTENCAO_IDENTIFICADA';
  route = 'pacotes';
  state.pacotes_apresentados = true;
} else if (persistedStatus === 'RECOMENDACAO_PRONTA' && state.pacote_recomendado) {
  const gargalo = Object.keys(PACKAGES).find(k => PACKAGES[k] === state.pacote_recomendado) ||
    state.gargalo_principal;
  if (gargalo) recommend(gargalo);
} else {
  runDiagnosis();
}

if (!nextQuestion) {
  state.ultima_pergunta = null;
  state.campos_pendentes = [];
}
// A trava de notificacao pertence apenas ao ciclo atual de HANDOFF_PENDENTE.
// Ao sair desse estado, libera um novo pedido humano futuro para o mesmo contato.
if (state.estado_funil !== 'HANDOFF_PENDENTE') {
  state.handoff_notificado_em = null;
  state.handoff_should_notify = false;
}

// O sinal de autorizacao e valido apenas para o turno em que foi dado; nao deve persistir
// e ser reaproveitado silenciosamente em turnos futuros.
state.autoriza_continuidade = null;
state.ultima_interacao_em = new Date().toISOString();

return [{
  json: {
    state,
    route,
    next_question: nextQuestion,
    decision,
    extraction: ex
  }
}];

const data = { ...$json };
const normalizado = $('Normalizar Evento').item.json;

const historicoItems = $('Formata Histórico').all();
const temMensagemAssistente = historicoItems.some(item => 
  String(item.json.context_message || '').startsWith('ASSISTENTE:')
);

const estadoAtual = $('Preparar estado do lead').item.json.lead_state;
const jaInteragiuAntes = !!estadoAtual.ultima_interacao_em;

data.is_first_interaction = !temMensagemAssistente && !jaInteragiuAntes;

if (data.route === 'handoff') {
  data.handoff = {
    status: 'HANDOFF_PENDENTE',
    should_notify: data.state.handoff_should_notify !== false,
    already_notified_at: data.state.handoff_notificado_em || null,
    notification_channel: 'whatsapp_z_api',
    notificacao_numero: '5500000000000',
    context: {
      lead_id: data.state.lead_id,
      nome: data.state.nome,
      empresa: data.state.empresa,
      segmento: data.state.segmento,
      intencao: data.state.intencao,
      gargalo: data.state.gargalo_principal,
      pacote: data.state.pacote_recomendado,
      ultima_mensagem: Array.isArray($('Novas Mensagens - Status : Processando ').item.json[' message'])
        ? $('Novas Mensagens - Status : Processando ').item.json[' message'].join(' | ')
        : $('Novas Mensagens - Status : Processando ').item.json[' message']
    }
  };
}

data.notification_route =
  data.route === 'handoff' && data.handoff?.should_notify
    ? 'handoff'
    : 'skip';

return [{ json: data }];

