const newMessagesRaw = $('Novas Mensagens - Status : Processando ').item.json[' message'];
const currentMessage = (Array.isArray(newMessagesRaw) ? newMessagesRaw.join(' ') : String(newMessagesRaw || '')).trim();
const asksPayment = /\b(pagamento|mensalidade|primeira mensalidade|cobrança|cobranca|vence|vencimento)\b/i.test(currentMessage);

const LOCKED_RESPONSES = {
  encerrado: 'Por aqui, esse atendimento já foi concluído. Se precisar de mais alguma coisa, é só chamar.',
  opt_out: 'Entendido. O atendimento automático será encerrado e não farei novas perguntas comerciais.'
};

if (LOCKED_RESPONSES[directive.route]) {
  return [{
    json: {
      response: LOCKED_RESPONSES[directive.route],
      validation_ok: true,
      validation_errors: [],
      state: directive.state,
      route: directive.route,
      handoff: directive.handoff || null
    }
  }];
}

let response = String($json.text ?? $json.output ?? '')
  .trim()
  .replace(/\*\*/g, '')
  .replace(new RegExp('^' + fence + '[^\\n]*\\n|' + fence + '$', 'g'), '')
  .replace(/^\s*[•*]\s+/gm, '- ')
  .trim();

const errors = [];

if (!response) errors.push('resposta_vazia');

if (/\b(garantimos|garantido|garantia de (vendas?|resultado|leads?|clientes?|faturamento|retorno)|certeza de (vendas?|resultado)|primeiro lugar no google|primeira posição no google|piloto automático|sem participação humana|sem intervenção humana|resultado imediato|resultados imediatos|aprovação (garantida|certa)|ROAS garantido|vendas no piloto)\b/i.test(response)) {
  errors.push('promessa_proibida');
}

if (directive.decision?.pacote_recomendado && !asksPayment &&
    !response.includes(directive.decision.pacote_recomendado)) {
  errors.push('pacote_ausente_ou_divergente');
}

if (directive.route === 'handoff' &&
    /já (transferi|encaminhei)|foi encaminhado|já está com (a|nossa) equipe/i.test(response)) {
  errors.push('handoff_ficticio');
}

const GREETING_PREFIX = 'Olá, tudo bem? Sou o assistente virtual da Projeto de Portfólio, agência de automação e estratégia digital para pequenas empresas.';
const responseForQuestionCheck = response.startsWith(GREETING_PREFIX)
  ? response.slice(GREETING_PREFIX.length)
  : response;

const questions = responseForQuestionCheck.match(/\?/g) || [];
if (questions.length > 1) errors.push('mais_de_uma_pergunta');

const respostaTrimmed = response.trim();
const finalSuspeito = /(:|;|,|-|\/)\s*$/.test(respostaTrimmed);
const ultimaLinha = respostaTrimmed.split('\n').pop().trim();
const respostaCurta = respostaTrimmed.length < 120;
const perguntaObrigatoriaAusente = Boolean(directive.next_question) &&
  !response.includes(directive.next_question);
const marcadorDeListaSemConteudo = /^[-•*]\s*$/.test(ultimaLinha);

if (finalSuspeito && (respostaCurta || perguntaObrigatoriaAusente || marcadorDeListaSemConteudo)) {
  errors.push('resposta_possivelmente_truncada');
}

if (directive.next_question) {
  if (directive.is_first_interaction) {
    const respostaContemPerguntaCerta = response.includes(directive.next_question);
    const respostaContemSaudacao = response.startsWith(GREETING_PREFIX);
