    // Rede de seguranca no momento mais critico: se a IA errou ou omitiu o pacote na
    // recomendacao final, o cliente nao pode ficar sem resposta nenhuma sobre qual
    // pacote o motor determinou. Aqui garantimos que o nome certo sempre chegue.
    response = 'Com base no que você me contou, o pacote mais indicado para o seu momento é o ' +
      directive.decision.pacote_recomendado + '. Quer que eu detalhe o que está incluído e como funciona a implantação?';
  } else {
    response = directive.next_question ||
      'Não consegui concluir essa orientação com segurança. Pode reformular sua última pergunta?';
  }
}

const handoffEmParalelo = ['PENDENTE','CONFIRMADO'].includes(String(directive.state?.handoff_status || '').toUpperCase());
const contextoComercialParaFechamento =
  Boolean(directive.decision?.pacote_recomendado) ||
  ['site_avulso','pacotes','comparacao'].includes(directive.route);

if (!errors.length &&
    !/\?\s*$/.test(response) &&
    !directive.next_question &&
    !handoffEmParalelo &&
    contextoComercialParaFechamento) {
  let fechamento;
  if (directive.decision?.pacote_recomendado) {
    fechamento = 'Faz sentido seguirmos com o ' + directive.decision.pacote_recomendado + '?';
  } else if (directive.route === 'site_avulso') {
    fechamento = 'Posso te ajudar com mais alguma coisa sobre o site?';
  } else {
    fechamento = 'Algum desses pacotes faz mais sentido para o seu momento agora?';
  }
  response = response.replace(/\s*(Se precisar de mais (alguma coisa|informações)[^.?!]*[.!])\s*$/i, '').trim();
  response = response + '\n\n' + fechamento;
}

return [{
  json: {
    response,
    validation_ok: errors.length === 0,
    validation_errors: errors,
    state: directive.state,
    route: directive.route,
    handoff: directive.handoff || null
  }
}];

const row = $json || {};
let state = {};

if (row.dados_json) {
  try {
    state = JSON.parse(row.dados_json);
  } catch (e) {
    state = {};
  }
}

// Garante identificador do lead mesmo se dados_json estiver vazio ou incompleto
if (!state.lead_id) {
  state.lead_id = $('Normalizar Evento').item.json.phone;
}

// Fallback para colunas persistidas separadamente, caso dados_json nao as tenha
if (row.estado_funil && !state.estado_funil) state.estado_funil = row.estado_funil;
if (row.intencao && !state.intencao) state.intencao = row.intencao;

// Estado padrao para lead novo (primeira interacao, sem historico salvo)
if (!state.estado_funil) state.estado_funil = 'NOVO';
if (!state.intencao) state.intencao = 'desconhecida';

return [{ json: { lead_state: state } }];
